begin;
create extension if not exists pgtap;
select plan(26);
select has_function('public','set_reservation_status_atomic',array['uuid','text'],'reservation status RPC exists');
select function_privs_are('public','set_reservation_status_atomic',array['uuid','text'],'authenticated',array['EXECUTE'],'authenticated can execute');
select function_privs_are('public','set_reservation_status_atomic',array['uuid','text'],'anon',array[]::text[],'anon cannot execute');
select function_privs_are('public','set_reservation_status_atomic',array['uuid','text'],'public',array[]::text[],'public cannot execute');
insert into auth.users(id,email,encrypted_password,raw_app_meta_data,raw_user_meta_data) values ('a2000000-0000-4000-8000-000000000001','status-owner@example.test','x','{}','{}'),('a2000000-0000-4000-8000-000000000002','status-outsider@example.test','x','{}','{}');
insert into public.organizations(id,name,slug,status,timezone) values ('a2000000-0000-4000-8000-000000000010','Status Org','status-org','active','UTC'),('a2000000-0000-4000-8000-000000000011','Other Org','other-org','active','UTC');
insert into public.roles(id,name,slug,permissions) values ('a2000000-0000-4000-8000-000000000020','Editor','status-editor',array['reservation.edit']),('a2000000-0000-4000-8000-000000000021','Viewer','status-viewer',array[]::text[]);
insert into public.users(id,auth_user_id,email,display_name) values ('a2000000-0000-4000-8000-000000000030','a2000000-0000-4000-8000-000000000001','status-owner@example.test','Status Owner'),('a2000000-0000-4000-8000-000000000031','a2000000-0000-4000-8000-000000000002','status-outsider@example.test','Status Outsider');
insert into public.profiles(id,user_id,organization_id,role_id,display_name) values ('a2000000-0000-4000-8000-000000000040','a2000000-0000-4000-8000-000000000030','a2000000-0000-4000-8000-000000000010','a2000000-0000-4000-8000-000000000020','Status Owner'),('a2000000-0000-4000-8000-000000000041','a2000000-0000-4000-8000-000000000031','a2000000-0000-4000-8000-000000000011','a2000000-0000-4000-8000-000000000021','Status Outsider');
insert into public.events(id,organization_id,name,event_type,status,start_at,timezone,venue,operational_model) values ('a2000000-0000-4000-8000-000000000050','a2000000-0000-4000-8000-000000000010','Status Event','event','active','2026-01-01T00:00:00Z','UTC','Status Venue','general'),('a2000000-0000-4000-8000-000000000051','a2000000-0000-4000-8000-000000000011','Other Event','event','active','2026-01-01T00:00:00Z','UTC','Other Venue','general');
insert into public.reservations(id,code,name,event_id,event_name,date,time,table_name,holder_name,holder_document,reservation_type,payment_status,status) values
('a2000000-0000-4000-8000-000000000060','STAT-0','Fixture 0','a2000000-0000-4000-8000-000000000050','Status Event','2026-01-01','20:00','T0','Holder','doc','General','Pending','Draft'),('a2000000-0000-4000-8000-000000000061','STAT-1','Fixture 1','a2000000-0000-4000-8000-000000000050','Status Event','2026-01-01','20:00','T1','Holder','doc','General','Pending','Pending'),('a2000000-0000-4000-8000-000000000062','STAT-2','Fixture 2','a2000000-0000-4000-8000-000000000050','Status Event','2026-01-01','20:00','T2','Holder','doc','General','Pending','Confirmed'),('a2000000-0000-4000-8000-000000000063','STAT-3','Fixture 3','a2000000-0000-4000-8000-000000000050','Status Event','2026-01-01','20:00','T3','Holder','doc','General','Pending','Checked In'),('a2000000-0000-4000-8000-000000000064','STAT-4','Fixture 4','a2000000-0000-4000-8000-000000000050','Status Event','2026-01-01','20:00','T4','Holder','doc','General','Pending','Completed'),('a2000000-0000-4000-8000-000000000065','STAT-5','Fixture 5','a2000000-0000-4000-8000-000000000050','Status Event','2026-01-01','20:00','T5','Holder','doc','General','Pending','Cancelled'),('a2000000-0000-4000-8000-000000000066','STAT-6','Fixture 6','a2000000-0000-4000-8000-000000000050','Status Event','2026-01-01','20:00','T6','Holder','doc','General','Pending','No Show'),('a2000000-0000-4000-8000-000000000070','STAT-O','Other','a2000000-0000-4000-8000-000000000051','Other Event','2026-01-01','20:00','TO','Other','doc','General','Pending','Pending'),('a2000000-0000-4000-8000-000000000071','STAT-D','Deleted','a2000000-0000-4000-8000-000000000050','Status Event','2026-01-01','20:00','TD','Deleted','doc','General','Pending','Pending');
update public.reservations set deleted_at=now() where id='a2000000-0000-4000-8000-000000000071';
insert into public.reservations(id,code,name,event_id,event_name,date,time,table_name,holder_name,holder_document,reservation_type,payment_status,status) values ('a2000000-0000-4000-8000-000000000067','STAT-7','Fixture 7','a2000000-0000-4000-8000-000000000050','Status Event','2026-01-01','20:00','T7','Holder','doc','General','Pending','Draft');
insert into public.guests(id,event_id,guest_name,reservation_name,reservation_code,reservation_id,event_name,event_status,invitation_sequence,invitation_code,carnet,delivery_status,admission_status,reservation_status,qr_status,table_id,table_name) select ('a2000000-0000-4000-8000-'||lpad((80+n)::text,12,'0'))::uuid,'a2000000-0000-4000-8000-000000000050','Guest '||n,'Holder','STAT-'||n,('a2000000-0000-4000-8000-'||lpad((60+n)::text,12,'0')),'Status Event','active',n::text,'CODE-'||n,'CARNET-'||n,'pending','Pendiente',s,'Activo','TABLE-SENTINEL','Table Sentinel' from (values (0,'Draft'),(1,'Pending'),(2,'Confirmed'),(3,'Checked In'),(4,'Completed'),(5,'Cancelled'),(6,'No Show')) v(n,s);
insert into public.checkins(id,event_id,guest_id,reservation_id,method,checked_in_at,operator,status) values ('a2000000-0000-4000-8000-000000000090','a2000000-0000-4000-8000-000000000050','a2000000-0000-4000-8000-000000000083','a2000000-0000-4000-8000-000000000063','manual','2026-01-01T20:00:00Z','sentinel','active');
select set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000067','Confirmed')->>'changed'),'true','Draft to Confirmed changes');
select is((public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000062','Confirmed')->>'changed'),'false','Confirmed same status no-op');
select is((public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000060','Pending')->>'changed'),'true','Draft to Pending changes');
select is((select status from public.reservations where id='a2000000-0000-4000-8000-000000000060'),'Pending','Draft to Pending persists');
select is((select reservation_status from public.guests where id='a2000000-0000-4000-8000-000000000080'),'Pending','guest follows transition');
select is((public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000060','Confirmed')->>'previous_status'),'Pending','previous status returned');
select is((public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000060','Pending')->>'changed'),'true','Confirmed to Pending changes');
select is((public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000060','Pending')->>'changed'),'false','same status no-op');
select is((select admission_status||':'||qr_status||':'||table_id from public.guests where id='a2000000-0000-4000-8000-000000000080'),'Pendiente:Activo:TABLE-SENTINEL','untouched guest fields');
select is((select count(*)::int from public.checkins where id='a2000000-0000-4000-8000-000000000090'),1,'checkin untouched');
select throws_ok($$select public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000061','Draft')$$,'22023','reservation_status_transition_not_allowed','Pending to Draft rejected');
select throws_ok($$select public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000061','Cancelled')$$,'22023','reservation_status_transition_not_allowed','generic cancel rejected');
select throws_ok($$select public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000063','Pending')$$,'22023','reservation_status_transition_not_allowed','checked in rejected');
select throws_ok($$select public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000064','Pending')$$,'22023','reservation_status_transition_not_allowed','completed rejected');
select throws_ok($$select public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000065','Pending')$$,'22023','reservation_status_transition_not_allowed','cancelled rejected');
select throws_ok($$select public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000066','Pending')$$,'22023','reservation_status_transition_not_allowed','no show rejected');
select throws_ok($$select public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000061','Bogus')$$,'22023','reservation_status_transition_not_allowed','invalid target rejected');
select throws_ok($$select public.set_reservation_status_atomic('a2002000-0000-4000-8000-000000000061','Pending')$$,'P0002','reservation_not_found','missing reservation rejected');
select throws_ok($$select public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000071','Pending')$$,'P0002','reservation_not_found','deleted reservation rejected');
select throws_ok($$select public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000070','Confirmed')$$,'42501','reservation_forbidden','cross organization rejected');
select set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000061','Confirmed')$$,'42501','reservation_forbidden','insufficient permission rejected');
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select public.set_reservation_status_atomic('a2000000-0000-4000-8000-000000000061','Confirmed')$$,'28000','reservation_unauthenticated','unauthenticated rejected');
select * from finish();
rollback;
